mapper.update:
UPDATE account_lifecycle_operation
SET restricted_auth_epoch = #{restrictedAuthEpoch},
    updated_at = #{updatedAt}
WHERE operation_no = #{operationNo}
  AND customer_id = #{customerId}
  AND status IN ('REQUESTED', 'FENCED', 'VALIDATING', 'BLOCKED', 'EXECUTING',
                 'RETRY_PENDING', 'MANUAL_REVIEW')

UPDATE account_lifecycle_operation
SET status = #{targetStatus},
    row_version = row_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND row_version = #{expectedRowVersion}

UPDATE account_lifecycle_operation
SET status = 'FENCED',
    restricted_auth_epoch = #{restrictedAuthEpoch},
    applied_lifecycle_version = #{appliedLifecycleVersion},
    fenced_at = #{fencedAt},
    row_version = row_version + 1,
    updated_at = #{fencedAt}
WHERE id = #{id}
  AND status = 'REQUESTED'
  AND row_version = #{expectedRowVersion}

UPDATE account_lifecycle_operation
SET status = 'EXECUTING', execution_started_at = #{startedAt},
    row_version = row_version + 1, updated_at = #{startedAt}
WHERE id = #{id} AND operation_type = 'PHONE_CHANGE'
  AND status = 'REQUESTED' AND row_version = #{expectedRowVersion}

UPDATE account_lifecycle_operation
SET status = 'COMPLETED', applied_lifecycle_version = #{appliedLifecycleVersion},
    restricted_auth_epoch = #{newAuthEpoch},
    completed_at = #{completedAt}, row_version = row_version + 1, updated_at = #{completedAt}
WHERE id = #{id} AND operation_type = 'PHONE_CHANGE'
  AND status = 'EXECUTING' AND row_version = #{expectedRowVersion}
